#!/usr/bin/env node
/**
 * Generate `src/components.d.ts` when it is missing, so `tsc --noEmit` can resolve the
 * `mud-*` JSX and `HTMLMud*Element` types.
 *
 * The file is git-ignored (it is regenerated by every Stencil build, and the package ships its
 * own copy in dist/types/), so a fresh clone and every CI checkout start without it. When it is
 * already present this does nothing, which keeps `yarn typecheck` on the pre-commit hook as fast
 * as before; refreshing a stale copy after an API change is still `yarn build`'s job, as it was
 * when the file was tracked.
 */
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const DTS = fileURLToPath(new URL('../src/components.d.ts', import.meta.url));

if (!existsSync(DTS)) {
  console.log('ensure-components-dts: src/components.d.ts is missing; running `stencil build --dev`');
  const run = spawnSync('yarn', ['stencil', 'build', '--dev'], {
    cwd: ROOT,
    stdio: 'inherit',
    shell: process.platform === 'win32',
  });
  if (run.error) throw run.error;
  if (run.status !== 0 || !existsSync(DTS)) {
    console.error('ensure-components-dts: the Stencil build did not produce src/components.d.ts');
    process.exitCode = run.status || 1;
  }
}
